class _CacheEntry<T> {
  final T value;
  final int expiresAt;

  _CacheEntry(this.value, this.expiresAt);
}

class Cache<T> {
  final int ttlMs;
  final int maxSize;
  final Map<String, _CacheEntry<T>> _data = {};

  Cache({required this.ttlMs, this.maxSize = 100});

  void put(String key, T value) {
    _data[key] = _CacheEntry(value, DateTime.now().millisecondsSinceEpoch + ttlMs);
  }

  T? get(String key) {
    final entry = _data[key];
    if (entry == null) return null;
    if (DateTime.now().millisecondsSinceEpoch > entry.expiresAt) {
      _data.remove(key);
      return null;
    }
    return entry.value;
  }

  void remove(String key) {
    _data.remove(key);
  }

  void clear() {
    _data.clear();
  }

  int get length => _data.length;

  bool get isFull => _data.length >= maxSize;

  void cleanup() {
    final now = DateTime.now().millisecondsSinceEpoch;
    _data.removeWhere((key, entry) => now > entry.expiresAt);
  }

  Map<String, T> getAll() {
    cleanup();
    return _data.map((key, entry) => MapEntry(key, entry.value));
  }
}

void main() {
  final cache = Cache<String>(ttlMs: 1000, maxSize: 3);
  cache.put('name', 'Alice');
  cache.put('city', 'HCM');

  print('Name: ${cache.get("name")}');
  print('Length: ${cache.length}');
  print('Full: ${cache.isFull}');
  print('All: ${cache.getAll()}');
}

