class MigrationRunner {
  int currentVersion;
  final Map<int, String Function(Map<String, dynamic>)> _migrations = {};

  MigrationRunner(this.currentVersion);

  void register(int version, String Function(Map<String, dynamic>) up) {
    _migrations[version] = up;
  }

  Map<String, dynamic> migrate(Map<String, dynamic> data, int targetVersion) {
    if (targetVersion <= currentVersion) return data;

    final versions = _migrations.keys.where((v) => v > currentVersion && v <= targetVersion).toList()..sort();

    var result = Map<String, dynamic>.from(data);
    for (final version in versions) {
      final migration = _migrations[version];
      if (migration != null) {
        result = migration(result);
      }
    }

    currentVersion = targetVersion;
    return result;
  }

  int get latestVersion {
    if (_migrations.isEmpty) return currentVersion;
    return _migrations.keys.reduce((a, b) => a > b ? a : b);
  }

  bool needsMigration(int targetVersion) {
    return targetVersion > currentVersion;
  }

  String describe() {
    final versions = _migrations.keys.toList()..sort();
    return 'MigrationRunner(current=$currentVersion, registered=[${versions.join(', ')}])';
  }
}

void main() {
  final runner = MigrationRunner(1);
  runner.register(2, (data) => {...data, 'name_upper': data['name'].toString().toUpperCase()});
  runner.register(3, (data) => {...data, 'schema_version': 3});

  print(runner.describe());
  print('Latest version: ${runner.latestVersion}');
  print('Needs migration to 3: ${runner.needsMigration(3)}');

  final data = {'name': 'alice', 'version': 1};
  final migrated = runner.migrate(data, 3);
  print('Migrated: $migrated');
  print('Runner version: ${runner.currentVersion}');
}

