class SettingsManager {
  final Map<String, dynamic> _defaults;
  final Map<String, dynamic> _overrides = {};

  SettingsManager(Map<String, dynamic> defaults) : _defaults = Map.from(defaults);

  void set(String key, dynamic value) {
    _overrides[key] = value;
  }

  dynamic get(String key) {
    if (_overrides.containsKey(key)) return _overrides[key];
    return _defaults[key];
  }

  dynamic getWithFallback(String key, dynamic fallback) {
    final value = get(key);
    return value ?? fallback;
  }

  bool hasOverride(String key) => _overrides.containsKey(key);

  void removeOverride(String key) {
    _overrides.remove(key);
  }

  Map<String, dynamic> getAll() {
    return {..._defaults, ..._overrides};
  }

  void reset() {
    _overrides.clear();
  }

  int get overrideCount => _overrides.length;

  String describe() => 'Settings(defaults=${_defaults.length}, overrides=${_overrides.length})';
}

void main() {
  final settings = SettingsManager({'theme': 'light', 'lang': 'vi', 'fontSize': 14});
  print(settings.describe());
  print('Theme: ${settings.get("theme")}');

  settings.set('theme', 'dark');
  settings.set('fontSize', 18);
  print('Theme after set: ${settings.get("theme")}');
  print('Overrides: ${settings.overrideCount}');
  print('All: ${settings.getAll()}');

