class StorageStats {
  final List<Map<String, dynamic>> entries;

  StorageStats(this.entries);

  int get totalEntries => entries.length;

  int get totalSizeBytes {
    return entries.fold<int>(0, (sum, entry) {
      final entrySize = entry.values.fold<int>(0, (s, v) => s + v.toString().length);
      return sum + entrySize;
    });
  }

  Map<String, int> get fieldCounts {
    final counts = <String, int>{};
    for (final entry in entries) {
      for (final key in entry.keys) {
        counts[key] = (counts[key] ?? 0) + 1;
      }
    }
    return counts;
  }

  List<String> get allFields {
    final fields = <String>{};
    for (final entry in entries) {
      fields.addAll(entry.keys);
    }
    final sorted = fields.toList()..sort();
    return sorted;
  }

  String get averageSize {
    if (entries.isEmpty) return '0.0 B';
    final avg = totalSizeBytes / entries.length;
    if (avg >= 1024) return '${(avg / 1024).toStringAsFixed(1)} KB';
    return '${avg.toStringAsFixed(1)} B';
  }

  String get largestEntry {
    if (entries.isEmpty) return 'Entry #0 (0B)';
    int maxSize = 0;
    int maxIndex = 0;
    for (int i = 0; i < entries.length; i++) {
      final size = entries[i].values.fold<int>(0, (s, v) => s + v.toString().length);
      if (size > maxSize) {
        maxSize = size;
        maxIndex = i;
      }
    }
    return 'Entry #${maxIndex + 1} (${maxSize}B)';
  }

  Map<String, dynamic> getSummary() {
    return {
      'totalEntries': totalEntries,
      'totalSizeBytes': totalSizeBytes,
      'fieldCount': fieldCounts.length,
      'averageSize': averageSize,
    };
  }

  String describe() {
    return 'StorageStats($totalEntries entries, ${totalSizeBytes}B, ${fieldCounts.length} fields)';
  }
}

void main() {
  final entries = [
    {'name': 'Alice', 'age': '25'},
    {'name': 'Bob', 'age': '30', 'city': 'HN'},
  ];
  final stats = StorageStats(entries);
  print(stats.describe());
  print('Fields: ${stats.allFields}');
  print('Field counts: ${stats.fieldCounts}');
  print('Largest: ${stats.largestEntry}');
  print('Summary: ${stats.getSummary()}');
}
